text:
Your water tracker is below: tap + after each glass, and it fills up toward 8.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Segoe UI, sans-serif; text-align: center; padding: 24px; color: #1b2a33; }
  h1 { font-size: 20px; margin: 0 0 16px; }
  .count { font-size: 48px; font-weight: 600; margin: 8px 0; }
  .glasses { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; margin: 16px 0; }
  .g { width: 28px; height: 40px; border: 2px solid #4a9fd4; border-radius: 4px 4px 8px 8px; background: #fff; }
  .g.full { background: #4a9fd4; }
  button { font-size: 20px; width: 56px; height: 56px; border-radius: 50%; border: none; background: #4a9fd4; color: #fff; margin: 0 8px; cursor: pointer; }
  button.small { width: auto; height: auto; border-radius: 6px; font-size: 13px; padding: 6px 12px; background: #e3edf3; color: #1b2a33; margin-top: 20px; }
  #msg { min-height: 24px; color: #2e7d32; font-weight: 600; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div class="count"><span id="n">0</span> / 8</div>
  <div class="glasses" id="glasses"></div>
  <div id="msg"></div>
  <button id="minus" aria-label="Remove a glass">-</button>
  <button id="plus" aria-label="Add a glass">+</button>
  <div><button class="small" id="reset">Reset today</button></div>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var count = 0;
  try {
    var saved = JSON.parse(localStorage.getItem("water") || "{}");
    if (saved.date === today) count = saved.count || 0;
  } catch (e) {}

  function save() {
    try { localStorage.setItem("water", JSON.stringify({ date: today, count: count })); } catch (e) {}
  }

  function render() {
    document.getElementById("n").textContent = count;
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < count ? " full" : "");
      box.appendChild(d);
    }
    document.getElementById("msg").textContent =
      count >= GOAL ? "Goal reached. Well done!" : (GOAL - count) + " to go";
  }

  document.getElementById("plus").onclick = function () { count++; save(); render(); };
  document.getElementById("minus").onclick = function () { if (count > 0) count--; save(); render(); };
  document.getElementById("reset").onclick = function () { count = 0; save(); render(); };
  render();
</script>
</body>
</html>
```

It starts fresh each day, and goes past 8 if you keep drinking. If your screen doesn't keep the count after closing, tell me and I'll save it as a file you can open anytime.
